public class AccessExample {
    public int publicField = 1;       // accessible everywhere
    protected int protectedField = 2; // same package + subclasses
    int defaultField = 3;              // same package only
    private int privateField = 4;      // same class only

    public int getPrivate() {          // public accessor
        return privateField;
    }

    void accessAll() { // same class — can access everything
        System.out.println(publicField + protectedField
            + defaultField + privateField); // all accessible
    }
}

