Composition Over Inheritance:
// Composition approach
interface Engine {
    void start();
    int getHorsepower();
}

class ElectricEngine implements Engine {
    @Override public void start() { System.out.println("Electric motor silent start"); }
    @Override public int getHorsepower() { return 200; }
}

class Car {
    private final Engine engine; // composition: Car HAS-A Engine

    Car(Engine engine) { // dependency injection
        this.engine = engine;
    }

    void start() {
        engine.start(); // delegation
        System.out.println("Car started with " + engine.getHorsepower() + " HP");
    }
}

// Easy to swap implementations at runtime
Car tesla = new Car(new ElectricEngine());
Car ferrari = new Car(() -> System.out.println("V12 roars")); // lambda

