String Pool & Interning:
// String literals are interned automatically
String a = "hello";
String b = "hello";
System.out.println(a == b); // true (same interned reference)

// new String creates a new object
String c = new String("hello");
System.out.println(a == c); // false (different objects)
System.out.println(a.equals(c)); // true (same value)

// intern() returns pooled reference
String d = c.intern();
System.out.println(a == d); // true (now same as pool)

// Compile-time constant expressions are interned
String e = "he" + "llo";
System.out.println(a == e); // true (compiler evaluates)

// Runtime expressions are NOT interned
String f = "he";
String g = f + "llo";
System.out.println(a == g); // false (runtime concat)

// -XX:StringTableSize=1000003 (tune pool size)
// -XX:+UseStringDeduplication (G1 GC dedup)

// Pool inspection (Java 8u20+)
// int count = ...; no public API for pool size

// Best practice: use string literals, not new String()
