Try-With-Resources Deep:
import java.io.*;
import java.sql.*;

// Multiple resources
String url = "jdbc:postgresql://localhost/mydb";
try (Connection conn = DriverManager.getConnection(url, "user", "pass");
     PreparedStatement stmt = conn.prepareStatement("SELECT 1");
     ResultSet rs = stmt.executeQuery()) {

    while (rs.next()) {
        System.out.println(rs.getInt(1));
    }
} catch (SQLException e) {
    System.err.println("DB error: " + e.getMessage());
    for (Throwable suppressed : e.getSuppressed()) {
        System.err.println("Suppressed: " + suppressed);
    }
}
// All three resources auto-closed in reverse order

// Custom AutoCloseable
class Resource implements AutoCloseable {
    public Resource() { System.out.println("Acquired"); }
    public void use() { System.out.println("Used"); }
    @Override public void close() { System.out.println("Closed"); }
}

try (var res = new Resource()) {
    res.use();
}
// Acquired → Used → Closed

