Primitive Streams & Optionals:
import java.util.stream.*;
import java.util.*;

// IntStream — avoids Integer boxing
int sum = IntStream.rangeClosed(1, 100)  // 1..100 inclusive
    .filter(n -> n % 2 == 0)
    .sum();

// Ranges
IntStream.range(0, 5)       // 0,1,2,3,4
IntStream.rangeClosed(0, 5); // 0,1,2,3,4,5

// Statistics
IntSummaryStatistics stats = IntStream.of(3, 7, 1, 9, 4)
    .summaryStatistics();
stats.getMin();  // 1
stats.getMax();  // 9
stats.getSum();  // 24
stats.getCount(); // 5
stats.getAverage(); // 4.8

// Convert to boxed
List<Integer> boxed = IntStream.range(0, 5)
    .boxed()
    .toList();

// mapToObj — produce any type
List<String> labels = IntStream.range(0, 3)
    .mapToObj(i -> "Item #" + i)
    .toList();

// Primitive optionals
OptionalInt maybeInt = IntStream.of(1, 2, 3).max();
int val = maybeInt.orElse(-1);

// LongStream / DoubleStream
DoubleStream.of(1.5, 2.5, 3.5).average().ifPresent(System.out::println);

// FlatMap with primitives
IntStream.range(1, 4)
    .flatMap(i -> IntStream.range(0, i))
    .forEach(System.out::print); // 001012

Functional Interfaces:
import java.util.function.*;

// Function<T,R> — maps input to output
Function<String, Integer> length = s -> s.length();
System.out.println(length.apply("Hello")); // 5

// Predicate<T> — tests a condition
Predicate<Integer> isEven = n -> n % 2 == 0;
System.out.println(isEven.test(4)); // true

// Consumer<T> — performs action, no return
Consumer<String> logger = msg -> System.out.println("LOG: " + msg);
logger.accept("User logged in");

