import java.util.stream.*;
import java.util.*;
import java.util.function.*;

record Person(String name, int age, String city) {}

var people = List.of(
    new Person("Alice", 30, "NYC"),
    new Person("Bob", 25, "SF"),
    new Person("Charlie", 30, "NYC"),
    new Person("Diana", 35, "SF"));

// Grouping by city
Map<String, List<Person>> byCity = people.stream()
    .collect(Collectors.groupingBy(Person::city));

// Grouping with downstream collector
Map<String, Long> countByCity = people.stream()
    .collect(Collectors.groupingBy(Person::city, Collectors.counting()));

// Grouping with age mapping
Map<String, Set<Integer>> agesByCity = people.stream()
    .collect(Collectors.groupingBy(Person::city,
        Collectors.mapping(Person::age, Collectors.toSet())));

// Partitioning (true/false)
Map<Boolean, List<Person>> partitioned = people.stream()
    .collect(Collectors.partitioningBy(p -> p.age() >= 30));

// toMap with merge function
Map<String, Integer> totalAgeByName = people.stream()
    .collect(Collectors.toMap(
        Person::name,
        Person::age,
        Integer::sum)); // merge duplicates

// teeing (Java 12+) — two collectors
record Stats(double min, double max, double avg) {}
Stats stats = people.stream()
    .mapToInt(Person::age)
    .boxed()
    .collect(Collectors.teeing(
        Collectors.summarizingInt(Integer::intValue),
        Collectors.averagingInt(Integer::intValue),
        (sum, avg) -> new Stats(sum.getMin(), sum.getMax(), avg)
    ));

// Custom collector
Collector<Person, ?, Map<String, Long>> custom = Collector.of(
    HashMap::new,                                         // supplier
    (map, person) -> map.merge(person.city(), 1L, Long::sum), // accumulator
    (m1, m2) -> { m2.forEach((k, v) -> m1.merge(k, v, Long::sum)); return m1; }, // combiner
    Collector.Characteristics.IDENTITY_FINISH);            // characteristics

