import java.io.*;
import java.nio.*;
import java.nio.channels.*;

// RandomAccessFile — arbitrary position I/O
RandomAccessFile raf = new RandomAccessFile("data.bin", "rw");
raf.seek(10); // move to byte position 10
raf.writeInt(42);
raf.seek(0);
int first = raf.readInt();
raf.close();

// Memory-mapped file (FileChannel + MappedByteBuffer)
try (RandomAccessFile file = new RandomAccessFile("large.dat", "rw");
     FileChannel channel = file.getChannel()) {

    // Map first 1KB of file into memory
    MappedByteBuffer buffer = channel.map(
        FileChannel.MapMode.READ_WRITE, 0, 1024);

    // Read/write through buffer (extremely fast)
    buffer.putInt(0, 100);
    buffer.putDouble(4, 3.14159);

    int val = buffer.getInt(0);
    double pi = buffer.getDouble(4);

    // Force changes to disk
    buffer.force();
} // channel and file auto-closed

