import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;
import java.util.stream.IntStream;

// AtomicInteger — lock-free counter
AtomicInteger counter = new AtomicInteger(0);
IntStream.range(0, 10_000).parallel().forEach(i -> counter.incrementAndGet());
System.out.println(counter.get()); // 10000 (correct, no race condition)

// AtomicReference
AtomicReference<String> config = new AtomicReference<>("initial");
config.compareAndSet("initial", "updated");
System.out.println(config.get()); // "updated"

// LongAdder (better for high contention)
LongAdder adder = new LongAdder();
IntStream.range(0, 100_000).parallel().forEach(i -> adder.add(1));
System.out.println(adder.sum()); // 100000

// ReentrantLock
Lock lock = new ReentrantLock(true); // fair = true
lock.lock();
try {
    // critical section
} finally {
    lock.unlock(); // always unlock in finally
}

// tryLock — non-blocking attempt
if (lock.tryLock()) {
    try {
        // critical section
    } finally {
        lock.unlock();
    }
} else {
    System.out.println("Could not acquire lock");
}

// ReadWriteLock (multiple readers, single writer)
ReadWriteLock rwLock = new ReentrantReadWriteLock();
Lock readLock = rwLock.readLock();
Lock writeLock = rwLock.writeLock();
int sharedData = 0;
// Readers acquire readLock, writers acquire writeLock

// Condition (like wait/notify but with multiple conditions)
ReentrantLock conditionLock = new ReentrantLock();
Condition notEmpty = conditionLock.newCondition();
// conditionLock.await(), conditionLock.signal()

ForkJoinPool & Parallel Streams:
import java.util.concurrent.*;
import java.util.stream.*;

// RecursiveTask for sum (divide-and-conquer)
class SumTask extends RecursiveTask<Long> {
    private static final int THRESHOLD = 10_000;
    private final int[] array;
    private final int start, end;

    SumTask(int[] array, int start, int end) {
        this.array = array;
        this.start = start;
        this.end = end;
    }

    @Override
    protected Long compute() {
        if (end - start <= THRESHOLD) {
            long sum = 0;
            for (int i = start; i < end; i++) sum += array[i];
            return sum;
        }
        int mid = start + (end - start) / 2;
        SumTask left = new SumTask(array, start, mid);
        SumTask right = new SumTask(array, mid, end);
        left.fork();      // queue left for async execution
        long rightResult = right.compute(); // compute right directly
        long leftResult = left.join();     // wait for left
        return leftResult + rightResult;
    }
}

int[] data = IntStream.range(0, 100_000).toArray();
Long sum = new ForkJoinPool().invoke(new SumTask(data, 0, data.length));
System.out.println(sum);

// Parallel stream (uses common pool)
long parallelSum = Arrays.stream(data).parallel().sum();

// Custom ForkJoinPool for parallel stream
ForkJoinPool customPool = new ForkJoinPool(8);
long customSum;
try {
    customSum = customPool.submit(
        () -> Arrays.stream(data).parallel().sum()).get();
} catch (Exception e) {
    throw new RuntimeException(e);
} finally {
    customPool.shutdown();
}

// ManagedBlocker
ForkJoinPool.managedBlock(new ForkJoinPool.ManagedBlocker() {
    @Override public boolean block() { /* blocking operation */; return true; }
    @Override public boolean isReleasable() { return false; }
});

