import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.*;
import jakarta.validation.constraints.*;

// Request DTO
record CreateUserRequest(
    @NotBlank String name,
    @Email String email,
    @Min(0) @Max(150) int age
) {}

// Response DTO
record UserResponse(long id, String name, String email) {}

// Error response
record ErrorResponse(int status, String message, long timestamp) {
    static ErrorResponse of(HttpStatus status, String message) {
        return new ErrorResponse(status.value(), message, System.currentTimeMillis());
    }
}

@RestController
@RequestMapping("/api/v1/users")
class UserApiController {

    @GetMapping
    public ResponseEntity<List<UserResponse>> getAll() {
        return ResponseEntity.ok(List.of());
    }

    @GetMapping("/{id}")
    public ResponseEntity<UserResponse> getById(@PathVariable long id) {
        // find or throw
        return ResponseEntity.ok(new UserResponse(id, "Alice", "alice@test.com"));
    }

    @PostMapping
    public ResponseEntity<UserResponse> create(
            @Valid @RequestBody CreateUserRequest request) {
        // validation errors return 400 automatically
        var created = new UserResponse(1, request.name(), request.email());
        return ResponseEntity.status(HttpStatus.CREATED).body(created);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(@PathVariable long id) {
        return ResponseEntity.noContent().build();
    }
}

// Global exception handler
@RestControllerAdvice
class GlobalExceptionHandler {
    @ExceptionHandler(NotFoundException.class)
    public ResponseEntity<ErrorResponse> handleNotFound(NotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
            .body(ErrorResponse.of(HttpStatus.NOT_FOUND, ex.getMessage()));
    }
}

