MDC & Structured Logging:
import org.slf4j.*;

public class OrderService {
    private static final Logger log = LoggerFactory.getLogger(OrderService.class);

    public void processOrder(String orderId, String userId) {
        // Set MDC context
        MDC.put("orderId", orderId);
        MDC.put("userId", userId);

        try {
            log.info("Processing order");
            // All log statements automatically include orderId and userId

            // MDC can be nested with child contexts
            try (MDC.MDCCloseable ignored = MDC.putCloseable("step", "validation")) {
                log.debug("Validating inventory");
            } // auto-removes "step"

            log.info("Order processed successfully");
        } catch (Exception e) {
            log.error("Order processing failed", e);
        } finally {
            MDC.clear(); // always clear in finally!
        }
    }
}

