import java.util.function.*;
import java.util.*;

// Function composition
Function<String, Integer> parse = Integer::parseInt;
Function<Integer, String> toString = Object::toString;
Function<String, String> parseThenString = parse.andThen(toString);
System.out.println(parseThenString.apply("42")); // "42"

// Predicate combination
Predicate<String> nonNull = Objects::nonNull;
Predicate<String> longerThan3 = s -> s.length() > 3;
Predicate<String> valid = nonNull.and(longerThan3);
System.out.println(valid.test("Hello")); // true
System.out.println(valid.test("ab"));    // false
System.out.println(valid.test(null));    // false

// Supplier for lazy/deferred
Supplier<Double> random = Math::random;

// Consumer chain
Consumer<String> log = s -> System.out.println("LOG: " + s);
Consumer<String> save = s -> System.out.println("SAVE: " + s);
Consumer<String> logAndSave = log.andThen(save);
logAndSave.accept("event");

// Primitive supplier
IntSupplier dice = () -> (int)(Math.random() * 6) + 1;
IntStream.generate(dice).limit(3).forEach(System.out::println);

// BiFunction
BiFunction<String, Integer, String> repeat = (s, n) -> s.repeat(n);
System.out.println(repeat.apply("Hi ", 3)); // "Hi Hi Hi "

