import java.util.*;
import java.util.concurrent.*;

// Checked collection — runtime type safety
List<String> checked = Collections.checkedList(
    new ArrayList<>(), String.class);
// checked.add(42); // ClassCastException at runtime

// Set from map (ConcurrentHashMap as Set)
Set<String> concurrentSet = Collections.newSetFromMap(
    new ConcurrentHashMap<>());
concurrentSet.add("one");
concurrentSet.add("two");

// Partition list
List<Integer> nums = List.of(1, 2, 3, 4, 5, 6, 7);
List<List<Integer>> partitions = new ArrayList<>();
int size = 3;
for (int i = 0; i < nums.size(); i += size) {
    partitions.add(nums.subList(i, Math.min(i + size, nums.size())));
}
System.out.println(partitions); // [[1, 2, 3], [4, 5, 6], [7]]

// Frequency and disjoint
List<String> list = List.of("a", "b", "a", "c");
System.out.println(Collections.frequency(list, "a")); // 2
System.out.println(Collections.disjoint(list, List.of("x", "y"))); // true

// Rotate
List<Integer> rotate = new ArrayList<>(List.of(1, 2, 3, 4, 5));
Collections.rotate(rotate, 2);
System.out.println(rotate); // [4, 5, 1, 2, 3]

// Unmodifiable vs immutable
List<String> unmod = Collections.unmodifiableList(list);
List<String> immut = List.copyOf(list); // Java 10+, truly immutable

