module com.example.myapp {
    // Required modules
    requires java.sql;
    requires org.slf4j;

    // Packages exported to other modules
    exports com.example.myapp.api;
    exports com.example.myapp.model;

    // Open package for reflection (Hibernate, Jackson, etc.)
    opens com.example.myapp.model to org.hibernate.orm;

    // Service provider
