Annotations:
import java.lang.annotation.*;

// Define a custom annotation
@Retention(RetentionPolicy.RUNTIME)  // available at runtime via reflection
@Target({ElementType.METHOD, ElementType.TYPE}) // can annotate methods and classes
public @interface LogExecution {
    String value() default "";
    boolean logParams() default true;
}

// Usage
@LogExecution("UserController")
public class UserController {

    @LogExecution(logParams = false)
    public String getUser(Long id) {
        return "User: " + id;
    }
}

// Processing with reflection
import java.lang.reflect.Method;

public class AnnotationProcessor {
    public static void process(Object obj) {
        Class<?> clazz = obj.getClass();

        // Class-level annotations
        LogExecution classAnnotation = clazz.getAnnotation(LogExecution.class);
        if (classAnnotation != null) {
            System.out.println("Class: " + classAnnotation.value());
        }

        // Method-level annotations
        for (Method method : clazz.getDeclaredMethods()) {
            LogExecution methodAnnotation = method.getAnnotation(LogExecution.class);
            if (methodAnnotation != null) {
                System.out.println("Method: " + method.getName()
                    + ", logParams: " + methodAnnotation.logParams());
            }
        }
    }
}

Vector API (Incubator/Preview):
import jdk.incubator.vector.*;

public class VectorExample {
    public static void main(String[] args) {
        float[] a = {1, 2, 3, 4, 5, 6, 7, 8};
        float[] b = {8, 7, 6, 5, 4, 3, 2, 1};
        float[] c = new float[8];

        var species = FloatVector.SPECIES_256;

        int i = 0;
        int upperBound = species.loopBound(a.length);
        for (; i < upperBound; i += species.length()) {
            var va = FloatVector.fromArray(species, a, i);
            var vb = FloatVector.fromArray(species, b, i);
            var vc = va.add(vb);           // SIMD add
            vc.intoArray(c, i);
        }
        // Tail loop for remaining elements
        for (; i < a.length; i++) {
            c[i] = a[i] + b[i];
        }

        System.out.println(java.util.Arrays.toString(c)); // [9,9,9,9,9,9,9,9]

        // Reduction
        float sum = FloatVector.fromArray(species, a, 0)
            .reduceLanes(VectorOperators.ADD);
        System.out.println("Sum: " + sum); // 36.0
    }
}

Foreign Function & Memory API:
import java.lang.foreign.*;
import java.lang.invoke.*;

// Allocate off-heap memory
Arena arena = Arena.ofConfined();
MemorySegment segment = arena.allocate(100);

// Write and read
segment.set(ValueLayout.JAVA_INT, 0, 42);
int value = segment.get(ValueLayout.JAVA_INT, 0);
System.out.println(value); // 42

// C string (null-terminated)
MemorySegment cString = arena.allocateUtf8String("Hello native!");

// Call C standard library function
Linker linker = Linker.nativeLinker();
SymbolLookup stdlib = linker.defaultLookup();

// Find puts function
MethodHandle puts = linker.downcallHandle(
    stdlib.find("puts").orElseThrow(),
    FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS)
);

try {
    int result = (int) puts.invoke(cString);
    System.out.println("puts returned: " + result);
} catch (Throwable e) {
    e.printStackTrace();
}

arena.close(); // frees memory

// MemoryLayout for C structs
// struct Point { int x; int y; };
StructLayout pointLayout = MemoryLayout.structLayout(
    ValueLayout.JAVA_INT.withName("x"),
    ValueLayout.JAVA_INT.withName("y")
);
VarHandle xHandle = pointLayout.varHandle(MemoryLayout.PathElement.groupElement("x"));
VarHandle yHandle = pointLayout.varHandle(MemoryLayout.PathElement.groupElement("y"));

MemorySegment point = arena.allocate(pointLayout);
xHandle.set(point, 0, 10);
yHandle.set(point, 0, 20);
System.out.println("Point: " + xHandle.get(point, 0) + ", " + yHandle.get(point, 0));

